use semio_framework_test_fixtures::fixture_text;
use super::*;
use semio_framework_value::{retained_clone::RetainedCloneSource,retirement::{RetireOwned,controlled::ControlledRetirement}};
#[derive(semio_framework_value::RetireOwned,Clone,Debug,PartialEq)]struct Row{title:Option<String>,count:i64,body:Vec<u8>}
#[derive(semio_framework_value::RetireOwned,Default,Clone,Debug,PartialEq)]struct Patch{title:Option<Option<String>>,count:Option<i64>,body:Option<Vec<u8>>}
std::thread_local!{static PROJECTIONS:std::cell::Cell<usize>=const{std::cell::Cell::new(0)};}
fn count_projection(){PROJECTIONS.with(|n|n.set(n.get()+1));}
struct Title;struct Count;struct Body;
impl RetainedRecordFieldProjection<Row,Patch,Option<String>> for Title{const PROJECT_WORK:u64=2;const INSTALL_WORK:u64=1;fn project(r:RetainedCloneRef<'_,Row>)->RetainedCloneRef<'_,Option<String>>{count_projection();r.project(0,|r|&r.title)}fn install(p:&mut Patch,v:Option<Option<String>>){p.title=v}}
impl RetainedRecordFieldProjection<Row,Patch,i64> for Count{const PROJECT_WORK:u64=2;const INSTALL_WORK:u64=1;fn project(r:RetainedCloneRef<'_,Row>)->RetainedCloneRef<'_,i64>{count_projection();r.project(1,|r|&r.count)}fn install(p:&mut Patch,v:Option<i64>){p.count=v}}
impl RetainedRecordFieldProjection<Row,Patch,Vec<u8>> for Body{const PROJECT_WORK:u64=2;const INSTALL_WORK:u64=1;fn project(r:RetainedCloneRef<'_,Row>)->RetainedCloneRef<'_,Vec<u8>>{count_projection();r.project(2,|r|&r.body)}fn install(p:&mut Patch,v:Option<Vec<u8>>){p.body=v}}
impl RetainedRecordChange<Row> for Patch{
 const FIELD_COUNT:usize=3;
 const EMPTY_WORK:u64=3;
 fn field_work(index:usize)->Result<u64,ValueError>{let work=match index{0=>boxed_record_field_work::<Row,Patch,Option<String>,Title>()?,1=>boxed_record_field_work::<Row,Patch,i64,Count>()?,2=>boxed_record_field_work::<Row,Patch,Vec<u8>,Body>()?,_=>return Err(invalid("test record field out of range"))};work.checked_add(1).ok_or_else(||invalid("test birth work overflow"))}
 fn empty_result()->Self{Self::default()}
 fn field_bytes(index:usize)->Result<usize,ValueError>{Ok(match index{0=>size_of::<RetainedRecordFieldChange<Row,Self,Option<String>,Title>>(),1=>size_of::<RetainedRecordFieldChange<Row,Self,i64,Count>>(),2=>size_of::<RetainedRecordFieldChange<Row,Self,Vec<u8>,Body>>(),_=>return Err(invalid("test record field out of range"))})}
 fn field(index:usize,work:u64,grant:RetainedCloneGrant,actual:&mut Option<usize>)->RetainedWorkOutcome<Option<(Box<dyn RetainedRecordChangeField<Row,Self>>,RetainedCloneProgress)>>{if work==0{return RetainedWorkOutcome{result:Ok(None),work:0}}let turn=match index{0=>boxed_record_field::<Row,Self,Option<String>,Title>(work.saturating_sub(1),grant,actual),1=>boxed_record_field::<Row,Self,i64,Count>(work.saturating_sub(1),grant,actual),2=>boxed_record_field::<Row,Self,Vec<u8>,Body>(work.saturating_sub(1),grant,actual),_=>RetainedWorkOutcome{result:Err(invalid("test record field out of range")),work:0}};RetainedWorkOutcome{result:turn.result,work:turn.work+1}}
}
fn observe<T>(f:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);(value,(heap.requested_bytes,heap.released_bytes))}
fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=4096,"original record action must fit authored4KiB quantum: {}",d.copy_bytes);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn source<T:RetireOwned+Sync+'static>(value:T)->RetainedCloneSource<T>{let mut admission=RetainedCloneSource::admission_owned(value,());let mut output=None;for _ in 0..64{if admission.terminal_is_empty(){break}let g=grant(admission.next_demand().unwrap());if admission.phase()=="ready"{admission.take_output(&mut output,g).result.unwrap();}else{let mut actual=None;admission.advance(g,&mut actual).result.unwrap();}}output.expect("staged source admission")}
fn close_source<T:RetireOwned+Sync+'static>(s:&mut RetainedCloneSource<T>){while !s.terminal_is_empty(){let g=grant(s.next_close_demand(4096).unwrap());assert!(s.close_step(g).result.unwrap().progress().fits(g));}}
fn drain<T:RetireOwned>(v:T){let mut c=ControlledRetirement::new(v).map_err(|(e,_)|e).unwrap();while !c.terminal_is_empty(){let g=grant(c.next_demand(4096).unwrap());assert!(c.step(g).unwrap().progress().fits(g));}}
fn row(v:&serde_json::Value)->Row{Row{title:v["title"].as_str().map(str::to_owned),count:v["count"].as_i64().unwrap(),body:v["body"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect()}}
fn patch(v:&serde_json::Value)->Patch{Patch{title:v.get("title").map(|v|v.as_str().map(str::to_owned)),count:v.get("count").map(|v|v.as_i64().unwrap()),body:v.get("body").map(|v|v.as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect())}}
fn exercise(v:&serde_json::Value,cut:Option<usize>,body:usize,work:u64,check_partial:bool){observe(||());let mut a=source(row(&v["authored"]));let mut o=source(row(&v["original"]));let mut foreign=source(row(&v["authored"]));let pointers=(a.borrow().get().title.as_ref().map(|text|text.as_ptr()),a.borrow().get().body.as_ptr(),o.borrow().get().title.as_ref().map(|text|text.as_ptr()),o.borrow().get().body.as_ptr());let(mut c,heap)=observe(RetainedRecordChangeOwner::<Row,Patch>::new);assert_eq!(heap,(0,0));let mut turns=0;while !c.ready()&&cut.is_none_or(|cut|turns<cut){let before_quote=PROJECTIONS.with(|n|n.get());let d=c.demand(body,work).unwrap();if check_partial{assert_eq!(PROJECTIONS.with(|n|n.get()),before_quote,"unadmitted demand must not inspect source fields");}let g=grant(d);if check_partial&&c.phase==4{let before=PROJECTIONS.with(|n|n.get());let mut marker=None;let denied=c.advance(a.borrow(),o.borrow(),body,work,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g},&mut marker);let selected=PROJECTIONS.with(|n|n.get()-before);assert!(marker.is_none());assert!(denied.work>=2*selected as u64);assert_eq!(denied.result.unwrap().progress(),Default::default());}let mut denied_actual=None;let(step,heap)=observe(||c.advance(a.borrow(),o.borrow(),body,work,RetainedCloneGrant{maximum_items:0,..g},&mut denied_actual).result.unwrap());assert!(denied_actual.is_none());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));let before_quote=PROJECTIONS.with(|n|n.get());let quoted=c.work_demand(body,work).unwrap();if check_partial{assert_eq!(PROJECTIONS.with(|n|n.get()),before_quote,"unadmitted work demand must not inspect source fields");}let mut denied_actual=None;let denied=c.advance(a.borrow(),o.borrow(),body,0,g,&mut denied_actual);assert!(denied_actual.is_none());assert_eq!(denied.work,0);assert_eq!(denied.result.unwrap().progress(),Default::default());let mut actual=None;let(turn,heap)=observe(||c.advance(a.borrow(),o.borrow(),body,work,g,&mut actual));assert!(turn.work>0&&turn.work<=quoted);let p=turn.result.unwrap().progress();if let Some(bytes)=actual{assert_eq!(bytes,p.retained_capacity_bytes);}assert!(p.fits(g));assert_eq!(heap.0,p.retained_capacity_bytes,"original record allocation receipt");assert_eq!(heap.1,p.released_bytes,"original record release receipt");turns+=1;assert!(turns<10000);}if turns>0&&!c.ready(){let g=grant(c.demand(body,work).unwrap());let mut actual=None;let turn=c.advance(foreign.borrow(),o.borrow(),body,work,g,&mut actual);assert!(turn.result.is_err());assert!(actual.is_none());}if cut.is_none(){let g=grant(c.take_demand().unwrap());let(out,p)=c.take(g).unwrap().unwrap();assert!(p.fits(g));assert_eq!(out,patch(&v["patch"]));let mut result=row(&v["original"]);if let Some(title)=out.title.as_ref(){result.title=title.clone();}if let Some(count)=out.count{result.count=count;}if let Some(body)=out.body.as_ref(){result.body=body.clone();}assert_eq!(result,row(&v["authored"]));drain(result);drain(out);}c.begin_close();while !c.terminal_is_empty(){let g=grant(c.close_demand(4096).unwrap());assert_eq!(c.close_step(RetainedCloneGrant{maximum_items:0,..g}).result.unwrap().progress(),Default::default());let quoted=c.close_work_demand(g.maximum_copy_bytes).unwrap();let(turn,heap)=observe(||c.close_step(g));assert!(turn.work>0&&turn.work<=quoted);let p=turn.result.unwrap().progress();assert!(p.fits(g));assert_eq!(heap.0,p.retained_capacity_bytes);assert_eq!(heap.1,p.released_bytes);}assert_eq!(observe(||drop(c)).1,(0,0));assert_eq!((a.borrow().get().title.as_ref().map(|text|text.as_ptr()),a.borrow().get().body.as_ptr(),o.borrow().get().title.as_ref().map(|text|text.as_ptr()),o.borrow().get().body.as_ptr()),pointers);close_source(&mut a);close_source(&mut o);close_source(&mut foreign);}
#[test]fn record_changes_original_sparse_fields_and_paid_frontier_match_neutral_cases(){let f:serde_json::Value=serde_json::from_str(fixture_text!("../../../🪡️field/🟰️change/🎚️record/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in f["cases"].as_array().unwrap(){exercise(row,None,f["bodyBytes"].as_u64().unwrap()as usize,f["workUnits"].as_u64().unwrap(),f["checkPartialDenialWork"].as_bool().unwrap());}}
#[test]fn record_changes_partial_original_output_and_child_frontier_close(){let f:serde_json::Value=serde_json::from_str(fixture_text!("../../../🪡️field/🟰️change/🎚️record/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in f["cases"].as_array().unwrap(){for cut in f["cancelCuts"].as_array().unwrap(){let cut=cut.as_u64().unwrap()as usize;exercise(row,Some(cut),f["bodyBytes"].as_u64().unwrap()as usize,f["workUnits"].as_u64().unwrap(),f["checkPartialDenialWork"].as_bool().unwrap());}}}
#[test]fn record_field_allocation_refusal_reports_attempt_and_preserves_custody(){let f:serde_json::Value=serde_json::from_str(fixture_text!("../../../🪡️field/🟰️change/🎚️record/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let case=&f["cases"][0];let body=f["bodyBytes"].as_u64().unwrap()as usize;let work=f["workUnits"].as_u64().unwrap();let mut a=source(row(&case["authored"]));let mut o=source(row(&case["original"]));let mut c=RetainedRecordChangeOwner::<Row,Patch>::new();while c.phase!=3{let g=grant(c.demand(body,work).unwrap());let mut actual=None;c.advance(a.borrow(),o.borrow(),body,work,g,&mut actual).result.unwrap();}let g=grant(c.demand(body,work).unwrap());let mut actual=None;let(turn,refused)=crate::test_allocation::refuse_one_allocation_on_this_thread(||c.advance(a.borrow(),o.borrow(),body,work,g,&mut actual));assert_eq!(refused,1);assert_eq!(actual,Some(0));assert!(turn.result.is_err());assert_eq!(c.phase,3);c.begin_close();while !c.terminal_is_empty(){let g=grant(c.close_demand(4096).unwrap());c.close_step(g).result.unwrap();}close_source(&mut a);close_source(&mut o);}

#[test]fn record_field_constructor_work_matches_neutral_vectors(){let rows:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/birth.json")).unwrap();for row in rows.as_array().unwrap(){let(actual,bytes)=match row["type"].as_str().unwrap(){"optionalText"=>(boxed_record_field_work::<Row,Patch,Option<String>,Title>(),size_of::<RetainedRecordFieldChange<Row,Patch,Option<String>,Title>>()),"integer"=>(boxed_record_field_work::<Row,Patch,i64,Count>(),size_of::<RetainedRecordFieldChange<Row,Patch,i64,Count>>()),"bytes"=>(boxed_record_field_work::<Row,Patch,Vec<u8>,Body>(),size_of::<RetainedRecordFieldChange<Row,Patch,Vec<u8>,Body>>()),_=>unreachable!()};assert_eq!(actual.unwrap(),row["baseWork"].as_u64().unwrap()+u64::try_from(bytes*2).unwrap());}}
